#include "dst_bus_private.h"
#include "wake.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void dst_bus_task (void)
{   
  #if DBG_DST_BUS == 1
    dst_bus_dbg_print ("\nDst Bus Task Start", NULL , NULL) ;
  #endif
  
  for (;;)
    {   
      Dst_Bus_Q_Msg * dst_bus_q_msg = (Dst_Bus_Q_Msg *) q_remove (dst_bus_vars.q_pending, 1000) ;

        
      if (dst_bus_q_msg)
        {   
          wake_enter();
          
          // Validare callback pentru a evita crash-ul
          if(dst_bus_q_msg->callback != NULL)
            {
              dst_bus_q_msg->callback(dst_bus_q_msg->msg);
            }

          q_return((Q_Msg *) dst_bus_q_msg);
          wake_leave();
        }
      else if(dst_bus_vars.do_err_save)
        {          
          dst_bus_vars.do_err_save = FALSE ;

          dst_bus_err_save () ;
        }
    }
}
